-- =============================================================================
-- Legion Dalaran (map 1413) -- Phase C: SmartAI ambience
-- =============================================================================
-- Map 1413 already carries 453 creature_text lines across 151 NPCs, but only 3
-- NPCs had any AI, so none of it was ever spoken. This file ports the matching
-- SmartAI from the original source (LegionCore 7.3.5 zone 7502) so the city
-- talks, emotes and reacts.
--
-- Entry mapping was rebuilt by SPAWN POSITION: every source spawn was pushed
-- through the fitted map-1220 -> map-1413 transform (worst anchor residual
-- 0.004 yd, independently validated to 0.06 yd against the Dalaran Well POI)
-- and matched to our spawn rows; only pairs that ALSO have identical names were
-- kept (565 of 624 source entries).
--
-- Deliberately conservative -- SmartAI numeric ids above ~100 are per-fork
-- extensions and do NOT mean the same thing in 7.3.5 and 3.3.5, so only the
-- inherited ids are ported:
--   events  [0, 1, 10, 22, 25, 38, 52, 60, 61]
--           (UPDATE_IC, UPDATE_OOC, OOC_LOS, RECEIVE_EMOTE, RESET, DATA_SET, TEXT_OVER, UPDATE, LINK)
--   actions [1, 5, 10, 22, 45, 66, 72, 80]
--           (TALK, PLAY_EMOTE, RANDOM_EMOTE, SET_EVENT_PHASE, SET_DATA, SET_ORIENTATION, CLOSE_GOSSIP, CALL_TIMED_ACTIONLIST)
--   targets [0, 1, 2, 7, 16, 18, 21]
--           (NONE, SELF, VICTIM, ACTION_INVOKER, INVOKER_PARTY, PLAYER_DISTANCE, CLOSEST_PLAYER)
--   targets [11, 19] (CREATURE_DISTANCE, CLOSEST_CREATURE)
--           are supported too, with target_param1 remapped from the source
--           creature entry to ours; a row pointing at an unmapped NPC is dropped.
-- Any script containing anything else is skipped WHOLE, so no `link` chain is
-- left dangling. Nothing here casts spells, summons, or touches quests.
--
-- Selection is per EVENT CHAIN (a root row plus everything reachable through
-- `link`), so an NPC keeps its ambient chatter even when its quest chain is
-- dropped. Skipped for the record: 22 entries had no confident
-- mapping, 430 chains used non-portable events/actions,
-- 10 chains referenced a non-portable action list,
-- 114 entries ended up with nothing portable at all.
-- Kept: 67 chains across 43 NPCs.
--
-- Action lists are renumbered to the house convention our_entry*100+n so they
-- can never collide with an existing list.
--
-- Safe to re-run. Requires a worldserver restart.
-- =============================================================================

-- ---------- 1. enable SmartAI on the ported NPCs ----------
UPDATE `creature_template` SET `AIName` = 'SmartAI'
WHERE `entry` IN (3500011, 3500024, 3500026, 3500045, 3500046, 3500061, 3500068, 3500070, 3500072, 3500075, 3500076, 3500099, 3500101, 3500105, 3500112, 3500163, 3500165, 3500167, 3500169, 3500171, 3500173, 3500175, 3500177, 3500180, 3500184, 3500185, 3500187, 3500192, 3500207, 3500250, 3500304, 3500314, 3500318, 3500341, 3500354, 3500355, 3500357, 3500359, 3500360, 3500418, 3500491, 3500494, 3500512)
  AND `ScriptName` = '';

-- ---------- 2. creature scripts ----------
DELETE FROM `smart_scripts` WHERE `source_type` = 0 AND `entryorguid` IN (3500011, 3500024, 3500026, 3500045, 3500046, 3500061, 3500068, 3500070, 3500072, 3500075, 3500076, 3500099, 3500101, 3500105, 3500112, 3500163, 3500165, 3500167, 3500169, 3500171, 3500173, 3500175, 3500177, 3500180, 3500184, 3500185, 3500187, 3500192, 3500207, 3500250, 3500304, 3500314, 3500318, 3500341, 3500354, 3500355, 3500357, 3500359, 3500360, 3500418, 3500491, 3500494, 3500512);

-- ---------- 3. timed action lists ----------
DELETE FROM `smart_scripts` WHERE `source_type` = 9 AND `entryorguid` IN (350002400, 350002600, 350006800, 350007200, 350016300, 350016500, 350016700, 350016900, 350017100, 350017300, 350017500, 350017700, 350018000, 350018400, 350018500, 350018700, 350019200, 350049400, 350051200);
